      content: m.text || m.content || '',
    })),
    tools: [RECOMMENDATION_TOOL],
    tool_choice: { type: 'auto' },
  })

  const text = response.content.find(b => b.type === 'text')?.text ?? ''
  const toolUse = response.content.find(b => b.type === 'tool_use' && b.name === 'save_recommendation')
  const recommendation = toolUse?.input ?? null

  return { text, recommendation }
}

export async function getRecommendation(context) {
  const response = await client.messages.create({
    model: 'claude-haiku-4-5',
    max_tokens: 1024,
    system: [
      {
        type: 'text',
        text: SYSTEM_PROMPT,
        cache_control: { type: 'ephemeral' },
      },
    ],
    messages: [
      {
        role: 'user',
        content: buildUserMessage(context),
      },
    ],
  })

  const text = response.content.find(b => b.type === 'text')?.text ?? ''

  const jsonMatch = text.match(/\{[\s\S]*\}/)
  if (!jsonMatch) {
    throw new Error('AI negrąžino tinkamo atsakymo formato')
  }

  const result = JSON.parse(jsonMatch[0])

  if (!result.recommendedSubject || !result.explanation) {
    throw new Error('AI atsakyme trūksta laukų')
  }

  return result
}

import { Router } from 'express'
import { getChatResponse } from './ai.service.js'
import { saveRecommendation } from '../recommendations/recommendations.service.js'

const router = Router()

router.post('/', async (req, res, next) => {
  try {
    const { systemPrompt, messages } = req.body

    if (!Array.isArray(messages) || messages.length === 0) {
      return res.status(400).json({ error: 'messages yra privalomas' })
    }

    const { text, recommendation } = await getChatResponse(systemPrompt, messages)

    let fullText = text
    if (recommendation) {
      const userId = req.user?.id ?? null
      saveRecommendation(userId, { systemPrompt, messages }, recommendation).catch(() => {})

      const list = recommendation.subjects.map((subject, i) =>
        `**${subject}** — ${recommendation.explanations[i] ?? ''}`
      ).join('\n')
      fullText = text ? `${text}\n${list}` : list
    }

    res.json({ text: fullText })
  } catch (err) {
    next(err)
  }
})

