import pool from '../../config/database.js'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const TMP_DIR = path.resolve(__dirname, '../../../../uploads/tmp')

const ALLOWED_MIMES = [
  'application/pdf',
  'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  'text/plain',
]

const MAX_SIZE_BYTES = (Number(process.env.UPLOAD_MAX_SIZE_MB) || 100) * 1024 * 1024

export const upload = multer({
  dest: TMP_DIR,
  limits: { fileSize: MAX_SIZE_BYTES },
  fileFilter(_req, file, cb) {
    if (ALLOWED_MIMES.includes(file.mimetype)) {
      cb(null, true)
    } else {
      cb(new Error('Netinkamas failo tipas. Leidžiami: PDF, DOCX, TXT'))
    }
  },
})

export async function uploadDocument(req, res) {
  if (!req.file) {
    return res.status(400).json({ error: 'Failas nepateiktas' })
  }

  const { path: filePath, originalname, mimetype, size } = req.file

  try {
    const extractedText = await extractTextFromFile(filePath, mimetype)

    const [result] = await pool.execute(
      `INSERT INTO documents (user_id, filename, original_name, mime_type, size_bytes, extracted_text)
       VALUES (?, ?, ?, ?, ?, ?)`,
      [req.user.id, path.basename(filePath), originalname, mimetype, size, extractedText]
    )

    return res.status(201).json({
      id: result.insertId,
      originalName: originalname,
      mimeType: mimetype,
      sizeBytes: size,
      extractedLength: extractedText.length,
      extractedText,
    })
  } catch (err) {
    return res.status(422).json({ error: err.message })
  } finally {
    await deleteFile(filePath)
  }
}

import fs from 'fs/promises'
import mammoth from 'mammoth'
import { PDFParse } from 'pdf-parse'

const PROCESSING_TIMEOUT_MS = 15_000
const TEXT_LIMIT = 100_000

function withTimeout(promise, ms) {
  const timeout = new Promise((_, reject) =>
    setTimeout(
      () => reject(new Error('Failo apdorojimas viršijo 15 sekundžių limitą')),
      ms
    )
  )
  return Promise.race([promise, timeout])
}

async function doExtract(filePath, mimeType) {
  if (mimeType === 'application/pdf') {
    const buffer = await fs.readFile(filePath)
    const parser = new PDFParse({ data: buffer })
    try {
      const textResult = await parser.getText()
      return textResult.text ?? ''
    } finally {
      await parser.destroy()
    }
  }

  if (mimeType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
    const result = await mammoth.extractRawText({ path: filePath })
    return result.value
  }

  if (mimeType === 'text/plain') {
    return await fs.readFile(filePath, 'utf-8')
  }

  throw new Error('Netinkamas failo tipas. Leidžiami: PDF, DOCX, TXT')
}

export async function extractTextFromFile(filePath, mimeType) {
  const text = await withTimeout(doExtract(filePath, mimeType), PROCESSING_TIMEOUT_MS)

  if (text.length > TEXT_LIMIT) {
    return text.slice(0, TEXT_LIMIT)
  }

  return text
}

export async function deleteFile(filePath) {
  try {
    await fs.unlink(filePath)
  } catch {
    // Failas jau ištrintas arba neegzistuoja
  }
}

